// Serialize [ourtypes.IFirst] as a JSON-able map.
//
// This function performs no dispatch! It is only used to serialize
// the properties. If you want to serialize an instance of
// [ourtypes.IFirst] with proper dispatch, call
// [ToJsonable].
func firstToMap(
	that ourtypes.IFirst,
) (result map[string]interface{}, err error) {
	result = make(map[string]interface{})

	result["texts"], err = serializeArray(that.Texts(), directToJsonable[string])
	if err != nil {
		mustSerializationError(err).prependName("Texts()")
		return
	}

	result["count"], err = int64ToJsonable(that.Count())
	if err != nil {
		mustSerializationError(err).prependName("Count()")
		return
	}

	if that.Kind() != nil {
		result["kind"], err = KindToJsonable(*(that.Kind()))
		if err != nil {
			mustSerializationError(err).prependName("Kind()")
			return
		}
	}

	result["modelType"] = "First"

	return
}

